# encode each expression as relations and test whether P is wife of a son of T
def rels(expr):
    toks=expr.split(); R=[]
    for i in range(1,len(toks),2): R.append((toks[i-1],toks[i],toks[i+1]))
    return R
def holds(expr):
    R=rels(expr)
    parent=set(); male=set(); wife=set()
    for a,op,b in R:
        if op=='+': parent.add((a,b))
        if op=='-': parent.add((a,b)); male.add(a)
        if op=='$': parent.add((b,a)); male.add(a)
        if op=='/': wife.add((a,b)); male.add(b)
        if op=='*': wife.add((b,a)); male.add(a)
    # spouse's children are also children
    ch=set(parent)
    for w,h in wife:
        for p,c in list(parent):
            if p==h: ch.add((w,c))
            if p==w: ch.add((h,c))
    # contradiction: P is parent of T
    if ('P','T') in ch: return False
    if any(a==b for a,b in ch): return False
    return any(('T',s) in ch and s in male and ('P',s) in wife for s in 'BKO')
