# cycle of faces around '&' in the same rotational sense: view gives (top,right) consecutive
import itertools
faces=['%','?','+','@','$']
sols=set()
for opp_amp in faces:
    ring=[f for f in faces if f!=opp_amp]
    for perm in itertools.permutations(ring[1:]):
        cyc=[ring[0]]+list(perm)
        nxt={cyc[i]:cyc[(i+1)%4] for i in range(4)}
        if nxt.get('%')=='?' and nxt.get('+')=='@':
            i=cyc.index('@'); sols.add(cyc[(i+2)%4])
assert len(sols)==1
r=sols.pop()
opts={'A':'$','B':'%','C':'&','D':'?'}
assert r==opts['D']
for k in 'ABC': assert r!=opts[k]
